-- Fakt kartochkalari orqa tomonining ruscha matni — 61-partiya:
-- Bahouddin Naqshband, Berdaq, Botir Zokirov.

UPDATE fact_cards SET detail_ru = 'Сайид Мухаммад Бахауддин ибн Сайид Джалолиддин родился в 1318 году в селении Касри Хиндуён близ Бухары. В источнике это селение приводится и под именем Касри Орифон. Источник: Ziyouz.com, раздел «Энциклопедические учёные, полководцы».' WHERE id = 1906;
UPDATE fact_cards SET detail_ru = 'Накшбанд с юных лет вступил на путь суфизма и изучал его тайны. Он основательно овладел Кораном, толкованием и хадисами. Источник: Ziyouz.com, раздел «Энциклопедические учёные, полководцы».' WHERE id = 1907;
UPDATE fact_cards SET detail_ru = 'Он занимался земледелием, а позже наносил разные узоры на шёлковые ткани, на железные и медные изделия. Именно за это ремесло ему и было дано прозвище «Накшбанд» — «наносящий узор». Источник: Ziyouz.com, раздел «Энциклопедические учёные, полководцы».' WHERE id = 1908;
UPDATE fact_cards SET detail_ru = 'Бахауддин Накшбанд считал своим духовным наставником и учителем Абдулхалика Гиждувани. Он развил учение своего наставника. Источник: Ziyouz.com, раздел «Энциклопедические учёные, полководцы».' WHERE id = 1909;
UPDATE fact_cards SET detail_ru = 'Накшбанд написал тринадцать сочинений по теории и практике суфизма. Среди них особое значение имеют такие сочинения, как «Хаётнома», «Далили ошикон», «Одоб ас-соликин». Источник: Ziyouz.com, раздел «Энциклопедические учёные, полководцы».' WHERE id = 1910;
UPDATE fact_cards SET detail_ru = 'Ходжа Бахауддин положил начало пути «накшбандия». Он широко проповедовал суфизм во многих городах Аравии, Ирана и Средней Азии. Источник: Ziyouz.com, раздел «Энциклопедические учёные, полководцы».' WHERE id = 1911;
UPDATE fact_cards SET detail_ru = 'Главная суть накшбандийства выражена в девизе «Даст ба кору, дил ба ёр!». Значение его — «Рука в деле, Бог в сердце». Источник: Ziyouz.com, раздел «Энциклопедические учёные, полководцы».' WHERE id = 1912;
UPDATE fact_cards SET detail_ru = 'Имя «Бахауддин» означает «слава веры». А за то, что он был человеком чудотворным, ему дали имя «Балогардон» — «отводящий беду». Источник: Ziyouz.com, раздел «Энциклопедические учёные, полководцы».' WHERE id = 1913;
UPDATE fact_cards SET detail_ru = 'В источнике сказано, что путь накшбандия избрали А. Темур, А. Навои, А. Джами, Махтумкули и другие великие люди. Это показывает, насколько широко разошлось это учение за века. Источник: Ziyouz.com, раздел «Энциклопедические учёные, полководцы».' WHERE id = 1914;
UPDATE fact_cards SET detail_ru = 'Ходжа Бахауддин Накшбанд умер в 1389 году в своём селении. В 1993 году в Узбекистане широко отмечалось 675-летие Бахауддина Накшбанда. Источник: Ziyouz.com, раздел «Энциклопедические учёные, полководцы».' WHERE id = 1915;

UPDATE fact_cards SET detail_ru = 'Бердах родился в 1827 году в Муйнакском районе Каракалпакстана. Он вырос в семье рыбака. Источник: Ziyouz.com.' WHERE id = 2007;
UPDATE fact_cards SET detail_ru = 'Настоящее имя поэта — Бердимурад, сын Каргабая. В народе он был известен под именем Бердах. Источник: Ziyouz.com.' WHERE id = 2008;
UPDATE fact_cards SET detail_ru = 'Бердах учился сперва в аульной школе, затем в медресе. Однако учение в медресе он не сумел довести до конца и был вынужден его оставить. Источник: Ziyouz.com.' WHERE id = 2009;
UPDATE fact_cards SET detail_ru = 'Творчество Бердаха началось в восемнадцать-девятнадцать лет с того, что он читал стихи, перебирая струны домбры. В двадцать пять лет его признали в народе одарённым поэтом. Источник: Ziyouz.com.' WHERE id = 2010;
UPDATE fact_cards SET detail_ru = 'Бердах — автор поэм «Родословная», «Хорезм», «Амангельды», «Айдос-бий» и «Глупый царь». Эти поэмы считаются образцами каракалпакской классической словесности. Источник: Ziyouz.com.' WHERE id = 2011;
UPDATE fact_cards SET detail_ru = 'Бердах написал такие стихи, как «Для народа», «Подать», «Придёт ли лето», «Не бывало», «Лучше». Главными темами в них были народная жизнь, несправедливость и тяжесть податей. Источник: Ziyouz.com.' WHERE id = 2012;
UPDATE fact_cards SET detail_ru = 'Бердах умер в 1900 году. В 1961 году сборник его стихов вышел на узбекском языке. Источник: Ziyouz.com.' WHERE id = 2013;

UPDATE fact_cards SET detail_ru = 'Батыр Закиров родился 26 апреля 1936 года в Москве. Его отец Карим Закиров был оперным певцом и народным артистом Узбекистана, мать Шохиста Саидова — актрисой и певицей. Закировы — династия артистов, внёсшая огромный вклад в узбекское музыкальное искусство XX века. Источник: Национальная энциклопедия Узбекистана, статья «Закировы» (ziyouz.com).' WHERE id = 2130;
UPDATE fact_cards SET detail_ru = '«Арабское танго» — одна из египетских песен, переработанных Батыром Закировым в эстрадной манере. Впервые он исполнил её в 1957 году на международном фестивале молодёжи и студентов в Москве. Источник: УзА — статья «Батыр Закиров и восточная музыка»; Национальная энциклопедия Узбекистана (ziyouz.com).' WHERE id = 2131;
UPDATE fact_cards SET detail_ru = 'Батыр Закиров учился на вокальном факультете Ташкентской государственной консерватории (1952–1957) и на режиссёрском факультете Ташкентского государственного института театрального и художественного искусства (1958–1962). Голос у него был лирико-драматический тенор. Источник: Национальная энциклопедия Узбекистана, статья «Закировы» (ziyouz.com).' WHERE id = 2132;
UPDATE fact_cards SET detail_ru = 'Батыр Закиров считается основоположником узбекского современного профессионального эстрадного пения. С 1978 года он был солистом «Узбекконцерта», а в 1965 году ему было присвоено звание народного артиста Узбекистана. Источник: Национальная энциклопедия Узбекистана, статья «Закировы» (ziyouz.com).' WHERE id = 2133;
UPDATE fact_cards SET detail_ru = 'Он исполнял на подлинном языке сочинения таких авторов, как Э. Масиас, Ж. Брель, Р. Шанкар, Фарид аль-Атраш, братья Рахбани. Великий турецкий писатель Назым Хикмет был поклонником его песен. Источник: Национальная энциклопедия Узбекистана (ziyouz.com); УзА — статья «Батыр Закиров и восточная музыка».' WHERE id = 2134;
UPDATE fact_cards SET detail_ru = 'Как живописец Батыр Закиров создал такие работы, как «Автопортрет», «Саратан», «Купола», писал рассказы, очерки и стихи. Он написал либретто к опере Икрама Акбарова «Барс согдийской земли» и переложил на узбекский «Маленького принца» и «Тень». Источник: Национальная энциклопедия Узбекистана, статья «Закировы» (ziyouz.com).' WHERE id = 2135;
UPDATE fact_cards SET detail_ru = 'Батыр Закиров снимался в фильмах «Когда цветут цветы», «Огненные дороги» и «Юность гения». В фильме «Огненные дороги» он создал образ великого индийского писателя Рабиндраната Тагора. Источник: Национальная энциклопедия Узбекистана, статья «Закировы» (ziyouz.com).' WHERE id = 2136;
UPDATE fact_cards SET detail_ru = 'Батыр Закиров умер 23 января 1985 года в Ташкенте. Как вспоминал композитор Икрам Акбаров, песня «Эй, сарбон» была создана в пору, когда певец готовился в московской больнице ко второй операции. Источник: Национальная энциклопедия Узбекистана (ziyouz.com); УзА — статья «Батыр Закиров и восточная музыка».' WHERE id = 2137;
